                lose.add((x, y))
    if (a, b) in lose:
        print(\"LOSE\")
        return
    for i in range(a + 1):
        for j in range(b + 1):
            if i == 0 and j == 0:
                continue
            if (a - i, b - j) in lose:
                print(\"WIN %d %d\" % (i, j))
